WITH latest_date AS (
  SELECT MAX(date) AS max_date
  FROM rulings
  WHERE uuid IN (
    SELECT uuid FROM cards WHERE name = 'Mishra''s Factory'
  )
)
SELECT COUNT(*) AS ruling_count
FROM rulings
WHERE uuid IN (
    SELECT uuid FROM cards WHERE name = 'Mishra''s Factory'
  )
  AND date = (SELECT max_date FROM latest_date);

SELECT COUNT(*) AS num_printings_in_power_band
FROM cards
WHERE power > 3 AND power <= 10;

SELECT SUM(reputation) AS total_reputation_uk
FROM users
WHERE location LIKE '%United Kingdom%' AND id IN (SELECT DISTINCT ownerUserId FROM posts WHERE ownerUserId IS NOT NULL);

WITH MajorsWithMembers AS (
  SELECT DISTINCT link_to_major AS major_id FROM member
),
TotalMajors AS (
  SELECT COUNT(*) AS total FROM major
),
MajorsWithNoMembers AS (
  SELECT COUNT(*) AS no_member_count FROM major
  WHERE major_id NOT IN (SELECT major_id FROM MajorsWithMembers)
)
SELECT ROUND((CAST(no_member_count AS FLOAT) / total) * 100, 2) AS percentage_no_members
FROM TotalMajors, MajorsWithNoMembers;

WITH chlorine_atoms AS (
  SELECT atom_id FROM atom WHERE element = 'Cl'
),
chlorine_bonded_atoms AS (
  SELECT atom_id2 AS bonded_atom FROM connected WHERE atom_id IN (SELECT atom_id FROM chlorine_atoms)
  UNION
  SELECT atom_id AS bonded_atom FROM connected WHERE atom_id2 IN (SELECT atom_id FROM chlorine_atoms)
)
SELECT COUNT(DISTINCT bonded_atom) AS count_bonded_atoms FROM chlorine_bonded_atoms;
